import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E6%96%87%E5%AD%97%E5%88%97%E3%83%9E%E3%83%83%E3%83%81.html","title":"文字列マッチ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.79,"words":238},"filePathRelative":"文字列マッチ.md"}`),a={name:`文字列マッチ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="文字列マッチ" tabindex="-1"><a class="header-anchor" href="#文字列マッチ"><span>文字列マッチ</span></a></h1><p>アルゴリズムの一分野である文字列マッチ。<a href="./アルゴリズム.html">アルゴリズム</a>。<a href="./Diff.html">Diff</a>とはちょっと問題設定が違うが関連分野。</p><p>ここでは<a href="./【書籍】IntroductionToAlgorithms.html">【書籍】IntroductionToAlgorithms</a>の文字列マッチを読んでいったメモを中心に。32.3のあたり。</p><h2 id="ノーテーション" tabindex="-1"><a class="header-anchor" href="#ノーテーション"><span>ノーテーション</span></a></h2><p><img src="/RandomThoughts/assets/0000-CH_4dG5U.png" alt="imgs/StringMatch/0000.png"></p><h2 id="有限オートマトン" tabindex="-1"><a class="header-anchor" href="#有限オートマトン"><span>有限オートマトン</span></a></h2><h3 id="ノーテーション-1" tabindex="-1"><a class="header-anchor" href="#ノーテーション-1"><span>ノーテーション</span></a></h3><p><img src="/RandomThoughts/assets/0001-D3yWw9ux.png" alt="imgs/StringMatch/0001.png"></p><h3 id="状態遷移" tabindex="-1"><a class="header-anchor" href="#状態遷移"><span>状態遷移</span></a></h3><p><img src="/RandomThoughts/assets/0002-CVM1oXBh.png" alt="imgs/StringMatch/0002.png"></p><h3 id="acceptとreject" tabindex="-1"><a class="header-anchor" href="#acceptとreject"><span>acceptとreject</span></a></h3><p>状態遷移を続けていって今の状態qがAのメンバならMはここまでの入力をacceptしたといい、そうでないなら入力はrejectされたという。</p><h2 id="knuth-morris-prattアルゴリズムとprefix関数" tabindex="-1"><a class="header-anchor" href="#knuth-morris-prattアルゴリズムとprefix関数"><span>Knuth-Morris-Prattアルゴリズムとprefix関数</span></a></h2><p>オートマトンは遷移関数の事前計算の計算量が多い。 そこでその改善にprefix関数を使ってオンデマンドに計算する、というのがKMPアルゴリズムのアイデア。</p><h3 id="prefix関数" tabindex="-1"><a class="header-anchor" href="#prefix関数"><span>Prefix関数</span></a></h3><p><img src="/RandomThoughts/assets/0003-eHHEmFoL.png" alt="imgs/StringMatch/0003.png"></p><p>Pqのsuffixになっているプレフィクスで最長なもの。プレフィクスなので長さだけで十分。 「Pqのsuffixになっている」というのが重要。</p><h3 id="prefix関数の構築-compute-prefix-function" tabindex="-1"><a class="header-anchor" href="#prefix関数の構築-compute-prefix-function"><span>Prefix関数の構築（COMPUTE-PREFIX-FUNCTION)</span></a></h3><p>帰納法的な作りになっているので理解が少しむずかしい。</p><ul><li>一つ前の時点でsuffixになっている文字列が無い＞先頭1文字がprefixになっているかどうかだけの問題</li><li>一つ前の時点でsuffixになっているprefixが見つかっている（kにはその最後のprefixの値が入っている） <ul><li>そのprefixに1文字足してどうなるか見る</li><li>1文字足して一致しなかったら同じsuffixのさらなるprefixになっているものを辿っていくと全てのsuffixになる候補を辿れるはず（ここが帰納的）</li></ul></li></ul><p>2文字以上のsuffixに一致するなら必ず一つ前のsuffixに一致しているはずである、そして一つ前までは既に全てパイに入っているはず、というのがポイント。</p><h3 id="prefix関数を使ったマッチのアルゴリズム" tabindex="-1"><a class="header-anchor" href="#prefix関数を使ったマッチのアルゴリズム"><span>Prefix関数を使ったマッチのアルゴリズム</span></a></h3><p>次の文字が一致しなかった時にパイを遡って次の文字と一致するprefixを探して続ける、というもの。 これがオーダーnになるのはなかなかきわどい分析が必要でちょっと難しいが、 アルゴリズムが正しい事とまぁまぁ早そうな事は容易に理解出来る。</p><h3 id="enhancedsuffixarrayのトップダウン" tabindex="-1"><a class="header-anchor" href="#enhancedsuffixarrayのトップダウン"><span>EnhancedSuffixArrayのトップダウン</span></a></h3><p><a href="./EnhancedSuffixArray.html">EnhancedSuffixArray</a>の「トップダウンとchildtab」の所にも文字列マッチのアルゴリズムがある。 lcptableとchildtabが必要。</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};